```javascript
const axios = require('axios'); // Make sure to install the 'axios' package before running this code

async function postMessageToSlack(text, channel) {
  try {
    const options = {
      method: 'post',
      url: `https://slack.com/api/chat.postMessage`,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${process.env.SLACK_TOKEN}` // Replace with your Slack bot token
      },
      data: {
        channel,
        text
      }
    };

    const response = await axios(options);

    if (response.status === 200 && response.data.ts) {
      console.log(`Message sent to ${channel} with timestamp ${response.data.ts}`);
    } else {
      throw new Error('Failed to send message to Slack');
    }
  } catch (error) {
    console.error(`Error posting message to Slack: ${error.message}`);
  }
}

// Usage example:
postMessageToSlack('Hello, world!', '#general');
```

