const { NestFactory } = require('@nestjs/core');
const typeorm = require('typeorm');
const AppModule = require('./app.module');
const jwt = require('jsonwebtoken');

// Define user roles and permissions
const roles = {
  ADMIN: ['CREATE_USER', 'EDIT_USER', 'DELETE_USER'],
  USER: ['READ_USER'],
};

// Middleware for checking permissions based on user role
function checkPermission(role, permission) {
  return roles[role].includes(permission);
}

async function main() {
  // Initialize TypeORM
  await typeorm.createConnection();

  // Create Nest application
  const app = await NestFactory.create(AppModule);

  // Set up JWT authentication middleware
  app.useGlobalGuards(new AuthGuard());

  app.listen(3000, () => {
    console.log('Application is running on port 3000');
  });

  class AuthGuard {
    canActivate(context) {
      const request = context.switchToHttp().getRequest();
      const token = request.cookies.token;

      if (!token) {
        throw new UnauthorizedException('No token provided');
      }

      try {
        const decoded = jwt.verify(token, process.env.JWT_SECRET);
        request.user = decoded;
      } catch (error) {
        throw new UnauthorizedException('Invalid token');
      }
    }

    async canActivateAsync(context) {
      const request = context.switchToHttp().getRequest();
      const routeHandler = (req: Request, res: Response, next: Function) => next();

      const { role } = request.user;
      const { permission } = context.args[0];

      if (!checkPermission(role, permission)) {
        throw new ForbiddenException('User does not have the required permission');
      }

      request.permissions = roles[role];
      return routeHandler(request, res);
    }
  }
}
```

