 To create a JavaScript function that returns all entries in an object where the nested key value matches a given string key in dot-notated format, you can use recursion with a helper function. Here's how you can write it:

```javascript
function findNestedEntry(obj, key) {
  for (let [k, v] of Object.entries(obj)) {
    if (typeof v === "object" && k === key || typeof v === "string" && k.startsWith(key + ".")) {
      if (v instanceof Array) {
        const result = [];
        for (const entry of v) {
          result.push(...findNestedEntry(entry, key.substring(key.lastIndexOf(".") + 1)));
        }
        return result;
      } else {
        return [v];
      }
    }

    if (typeof v === "object") {
      return [...findNestedEntry(v, key)];
    }
  }

  return [];
}

// Usage example:
const myObject = {
  a: {
    b: "example",
    c: {
      d: "match",
      e: ["match", "mismatch"],
      f: { g: "another match" }
    },
    x: "no match"
  },
  y: "no object"
};

console.log(findNestedEntry(myObject, 'a.c.d')); // ['match']
console.log(findNestedEntry(myObject, 'a.c.e[0]')); // ['match']
console.log(findNestedEntry(myObject, 'y')); // []
