2. Next, create a method to validate and extract the username from the JWT token. Here's an example of how you could implement this method:

```csharp
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;

public static string GetUsernameFromJwtToken(string jwtToken)
{
    try
    {
        // Handler for JWT tokens
        JwtSecurityTokenHandler tokenHandler = new JwtSecurityTokenHandler();

        // Parse the JWT token
        JwtSecurityToken jwtTokenObj = tokenHandler.ReadJwtToken(jwtToken);

        // Get the username claim value
        ClaimsPrincipal principal = jwtTokenObj.Principal;
        ClaimsIdentity identity = principal as ClaimsIdentity;
        string username = identity.FindFirst("sub").Value;

        return username;
    }
    catch (Exception ex)
    {
        throw new Exception("Invalid or expired JWT token.", ex);
    }
}
```

3. Now, you can call this method whenever you need to extract the username from a JWT token. For example, you might use this method inside an action in your controller:

```csharp
[Authorize]
[HttpGet]
public ActionResult<string> GetUserName()
{
    string jwtToken = Request.Headers["Authorization"].Value.Replace("Bearer ", "");
    string username = GetUsernameFromJwtToken(jwtToken);
    return Ok(username);
}
```

