#include <stdio.h>
#include <stdlib.h> // For malloc() and realloc()
#include <string.h> // For strlen()

// Function to concatenate two strings
char *str_concat(const char *str1, const char *str2) {
    size_t len1 = strlen(str1);
    size_t len2 = strlen(str2);
    size_t total_len = len1 + len2 + 1;
    char *result = (char *)malloc(total_len * sizeof(char));

    if (!result) {
        perror("Memory allocation failed");
        return NULL;
    }

    strcpy(result, str1);
    strcat(result, str2);

    free(str1); // Free the memory occupied by str1

    return result;
}

int main(int argc, char **argv) {
    int i;
    size_t total_len = 0;
    size_t len;
    char *cstring = NULL;

    for (i = 0; i < argc; ++i) {
        len = strlen(argv[i]) + 1; // Add one for the null terminator
        total_len += len;
    }

    // Allocate enough memory for the resulting cstring
    cstring = (char *)calloc(total_len, sizeof(char));
    if (!cstring) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    for (i = 0; i < argc; ++i) {
        len = strlen(argv[i]);
        strncat(cstring, argv[i], len); // Concatenate each argument
