@Injectable()
@NestMiddleware()
export class NodeEnvCheckerMiddleware implements NestMiddleware {
  private logger: Logger;

  constructor(logger: Logger) {
    this.logger = logger;
  }

  use(req: Request, res: Response, next: Function, _: Function): void {
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true' || nodeEnv === 'production') {
