    } else {
      this.logger.warn('NODE_ENV is not set to production mode. Returning false.');
      res.status(403).send(false);
    }
  }
}

export const IsProduction = createParamDecorator((data: unknown, ctx: ExecutionContext) => {
  const req = ctx.switchToHttp().getRequest();
  return req.app.get('isProduction');
});

export function CheckNodeEnvMiddleware(middlewareConsumer: MiddlewareConsumer): void {
  middlewareConsumer.apply(NodeEnvCheckerMiddleware).forRoutes('*');
}
```

This middleware checks the `NODE_ENV` environment variable in each request and returns `false` with a status code 403 if it's not set to `true` or `production`. If the environment variable has the expected value, the request proceeds as usual. The `CheckNodeEnvMiddleware` function is a helper function to apply the middleware to all routes using the `MiddlewareConsumer`.

Keep in mind that this implementation assumes you have a global `Logger` service available. If you don't, you might need to adapt the constructor signature and the usage of the logger instance accordingly.

