import { createContext, useState } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = useState([]);

  const addToast = (message) => {
    setToasts((prevToasts) => [...prevToasts, message]);
    setTimeout(() => {
      setToasts((prevToasts) => prevToasts.filter((_, index) => index !== prevToasts.length - 1));
    }, 3000); // Duration of the toast message
  };

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
      <div id="toast-container" className="fixed bottom-0 right-0 p-6 w-1/4 bg-white border border-gray-300 rounded-lg shadow-md dark:bg-gray-800 dark:border-gray-700">
        {toasts.map((toast, index) => (
          <div key={index} className="mb-2 text-sm text-gray-500 dark:text-gray-400">{toast}</div>
        ))}
      </div>
    </ToastContext.Provider>
  );
};
